SELECT *
FROM point_goods


        AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


        AND status = #{status}


ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM point_goods
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT o.*, g.name AS itemName, g.image AS itemImage, u.nickname AS userNickname, u.student_no AS userStudentNo FROM point_order o JOIN point_goods g ON o.item_id = g.item_id JOIN sys_user u ON o.user_id = u.user_id
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR g.name LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.student_no LIKE CONCAT('%', #{keyword}, '%'))
AND o.status = #{status}
ORDER BY o.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM point_order o JOIN point_goods g ON o.item_id = g.item_id JOIN sys_user u ON o.user_id = u.user_id
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR g.name LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.student_no LIKE CONCAT('%', #{keyword}, '%'))
AND o.status = #{status}
